-- Despatch windows on fixed dates, for the DAO tests.
--
-- 36_AMS_SHIPPING_WINDOWS generates the real ones relative to SYSDATE, which is right for a screen
-- and useless for a test: ShippingCalendarDAOImplTest queries an explicit range, and a moving date
-- would make it assert nothing. These four are the fixtures it needs - 9706 is full and 9707 is
-- closed, which is what lets the query's two exclusions actually be tested, and 9708 is in another
-- region so the region scoping is provable.
INSERT INTO AMS_TIMESLOTS (TIMESLOT_ID, CALL_TYPE_CD, REGION_CD, START_TM, END_TM, CAPACITY, RESERVED_COUNT, AVAILABLE_FL, DISPLAY_LABEL, TIME_ZONE)
